rule_tree.head:
match auth_state {
	= authenticated:
		match identity_group {
			= "guests": verdict drop
			_:
				match protocol {
					= tcp:
						match dst_port {
							= 8080: verdict allow
							_: verdict drop
						}
					= icmp: verdict allow
					_: verdict drop
				}
		}
	_: verdict drop
}
